// v0.46.0: the surface the session half drives — the real socket client, or the tape wearing its
// clothes. Structural on purpose: nothing below this line may care which one it holds.
type SessionClient = Pick<LunaWsClient, 'connect' | 'send' | 'close'>;
let wsClient: SessionClient | null = null;

private frame(at: number, frame: ServerEvent): void {
  // The same gate the real wsClient applies to every inbound frame — a script that would produce
  // an invalid frame fails here, at compile time, never in a visitor's browser.
  ServerEvent.parse(frame);
  this.cues.push({ at, kind: 'frame', frame });
}

async function synthesize(text: string, wavPath: string): Promise<void> {
  const plan = planTtsForward('speak', JSON.stringify({ text }), env);
  if (plan.kind !== 'speak') throw new Error(`tts plan: ${plan.kind === 'error' ? plan.message : plan.kind}`);
  const res = await fetch(plan.url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: plan.body });
  if (!res.ok) throw new Error(`api_v2 ${res.status}: ${(await res.text()).slice(0, 200)}`);
  writeFileSync(wavPath, new Uint8Array(await res.arrayBuffer()));
}
